package com.srenterprises.controller;
import com.srenterprises.dto.AuthDtos.*; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import com.srenterprises.security.*; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.crypto.password.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final UserRepository users; final PasswordEncoder encoder; final JwtService jwt; AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} @PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.findByEmailIgnoreCase(r.email()).isPresent())return ResponseEntity.status(409).body(java.util.Map.of("message","Email is already registered")); User u=new User();u.name=r.name();u.email=r.email().toLowerCase();u.phone=r.phone();u.passwordHash=encoder.encode(r.password());users.save(u);return ResponseEntity.status(201).body(new Token(jwt.issue(u.email,u.role.name()),u.role.name(),u.name));} @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody Login r){var u=users.findByEmailIgnoreCase(r.email()).orElse(null);if(u==null||!u.active||!encoder.matches(r.password(),u.passwordHash))return ResponseEntity.status(401).body(java.util.Map.of("message","Invalid email or password"));u.lastLoginAt=java.time.Instant.now();users.save(u);return ResponseEntity.ok(new Token(jwt.issue(u.email,u.role.name()),u.role.name(),u.name));} }
